//! Small wasm-bindgen transport around the typed Rust API.
//!
//! Browser code supplies randomness generated by WebCrypto as canonical seed
//! bytes; this module never falls back to a predictable local RNG. Proving
//! artifacts are passed as canonical arkworks proving-key bytes and are not
//! embedded in the wasm binary.

use rand_chacha::{ChaCha20Rng, rand_core::SeedableRng};
use serde::de::DeserializeOwned;
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use wasm_bindgen::prelude::*;

use crate::proof::{ArtifactSet, ProvingArtifacts, SetupMode, prove, verify_with_vk_bytes};
use crate::{
    Ciphertext, Commitment, FieldHex, PROFILE_HASH, ProofEnvelope, PublicKey, ReaderView,
    RecoveryMetadata, RecoveryPair, RecoveryRecord, SecretKey, Statement, WitnessWire,
};

#[derive(Deserialize)]
struct Request {
    method: String,
    #[serde(default)]
    params: Value,
}

#[derive(Serialize)]
struct KeyMaterial {
    secret_key: String,
    public_key: PublicKey,
}

fn js_error(error: impl std::fmt::Display) -> JsValue {
    JsValue::from_str(&error.to_string())
}

fn parse_json<T: DeserializeOwned>(value: &Value) -> Result<T, JsValue> {
    serde_json::from_value(value.clone()).map_err(js_error)
}

fn parse_seed(value: &str) -> Result<[u8; 32], JsValue> {
    let bytes = hex::decode(value).map_err(js_error)?;
    bytes
        .try_into()
        .map_err(|_| JsValue::from_str("seed must be 32 bytes"))
}

fn parse_public_key(value: &str) -> Result<PublicKey, JsValue> {
    serde_json::from_str(value)
        .or_else(|_| PublicKey::parse(value))
        .map_err(js_error)
}

fn parse_ciphertext(value: &str) -> Result<Ciphertext, JsValue> {
    serde_json::from_str(value).map_err(js_error)
}

fn parse_secret(value: &str) -> Result<SecretKey, JsValue> {
    let wire = crate::ScalarHex::parse(value).map_err(js_error)?;
    SecretKey::from_wire(&wire).map_err(js_error)
}

fn parse_amount(value: &Value, name: &str) -> Result<u64, JsValue> {
    let text = value
        .get(name)
        .and_then(Value::as_str)
        .ok_or_else(|| JsValue::from_str(&format!("{name} must be a decimal string")))?;
    crate::encoding::decimal_u64::parse(text).map_err(js_error)
}

fn parse_amount_u128(value: &Value, name: &str) -> Result<u128, JsValue> {
    let text = value
        .get(name)
        .and_then(Value::as_str)
        .ok_or_else(|| JsValue::from_str(&format!("{name} must be a decimal string")))?;
    crate::encoding::decimal_u128::parse(text).map_err(js_error)
}

fn keygen(seed_hex: &str) -> Result<String, JsValue> {
    let mut rng = ChaCha20Rng::from_seed(parse_seed(seed_hex)?);
    let secret = SecretKey::generate(&mut rng);
    serde_json::to_string(&KeyMaterial {
        secret_key: secret.to_wire().0,
        public_key: secret.public_key(),
    })
    .map_err(js_error)
}

fn encrypt_amount(public_key: &str, amount: u64, randomness: &str) -> Result<String, JsValue> {
    let key = parse_public_key(public_key)?;
    let randomness = crate::ScalarHex::parse(randomness)
        .map_err(js_error)?
        .to_scalar()
        .map_err(js_error)?;
    let ciphertext =
        Ciphertext::encrypt_with_randomness(&key, amount, randomness).map_err(js_error)?;
    serde_json::to_string(&ciphertext).map_err(js_error)
}

fn canonical_statement(statement_json: &str) -> Result<String, JsValue> {
    let statement: Statement = serde_json::from_str(statement_json).map_err(js_error)?;
    let slots = statement.public_slots().map_err(js_error)?;
    serde_json::to_string(&json!({
        "statement_kind": statement.kind().as_str(),
        "context_digest": slots.digest_wire(),
        "public_inputs": slots.public_inputs().into_iter().map(FieldHex::from).collect::<Vec<_>>(),
    }))
    .map_err(js_error)
}

fn prove_statement(
    statement_json: &str,
    witness_json: &str,
    proving_key_bytes: &[u8],
    seed_hex: &str,
) -> Result<String, JsValue> {
    let statement: Statement = serde_json::from_str(statement_json).map_err(js_error)?;
    let witness_wire: WitnessWire = serde_json::from_str(witness_json).map_err(js_error)?;
    let witness = witness_wire.into_witness().map_err(js_error)?;
    let artifacts =
        ProvingArtifacts::from_proving_key_bytes(proving_key_bytes, SetupMode::ImportedArtifact)
            .map_err(js_error)?;
    let mut set = ArtifactSet::empty();
    set.insert(statement.kind(), artifacts).map_err(js_error)?;
    let mut rng = ChaCha20Rng::from_seed(parse_seed(seed_hex)?);
    let envelope = prove(&statement, &witness, &set, &mut rng).map_err(js_error)?;
    serde_json::to_string(&envelope).map_err(js_error)
}

fn encrypt_views(params: &Value) -> Result<String, JsValue> {
    let keys: Vec<PublicKey> = parse_json(
        params
            .get("public_keys")
            .ok_or_else(|| JsValue::from_str("encrypt_views requires public_keys"))?,
    )?;
    if keys.is_empty() || keys.len() > 5 {
        return Err(JsValue::from_str(
            "encrypt_views requires one through five keys",
        ));
    }
    let amount = parse_amount(params, "amount")?;
    let mut rng = ChaCha20Rng::from_seed(parse_seed(
        params
            .get("seed_hex")
            .and_then(Value::as_str)
            .ok_or_else(|| JsValue::from_str("encrypt_views requires seed_hex"))?,
    )?);
    let mut views = Vec::with_capacity(keys.len());
    let mut recovery = Vec::with_capacity(keys.len());
    let mut randomness = Vec::with_capacity(keys.len());
    let mut recovery_randomness = Vec::with_capacity(keys.len());
    for key in keys {
        let (ciphertext, r) = Ciphertext::encrypt(&key, amount, &mut rng).map_err(js_error)?;
        let (low_limb, low_r) =
            Ciphertext::encrypt(&key, amount & u32::MAX as u64, &mut rng).map_err(js_error)?;
        let (high_limb, high_r) =
            Ciphertext::encrypt(&key, amount >> 32, &mut rng).map_err(js_error)?;
        views.push(ReaderView {
            reader_key: key,
            ciphertext,
        });
        recovery.push(crate::RecoveryPair {
            low_limb,
            high_limb,
        });
        randomness.push(crate::ScalarHex::from(r));
        recovery_randomness.push([
            crate::ScalarHex::from(low_r),
            crate::ScalarHex::from(high_r),
        ]);
    }
    serde_json::to_string(&json!({
        "views": views,
        "recovery": recovery,
        "randomness": randomness,
        "recovery_randomness": recovery_randomness,
    }))
    .map_err(js_error)
}

fn create_recovery_record(params: &Value) -> Result<String, JsValue> {
    let amount = parse_amount(params, "amount")?;
    let recipient_key: PublicKey = parse_json(
        params
            .get("recipient_key")
            .ok_or_else(|| JsValue::from_str("create_recovery_record requires recipient_key"))?,
    )?;
    let metadata: RecoveryMetadata = parse_json(
        params
            .get("metadata")
            .ok_or_else(|| JsValue::from_str("create_recovery_record requires metadata"))?,
    )?;
    let main_ciphertext: Ciphertext = parse_json(
        params.get("main_ciphertext").ok_or_else(|| {
            JsValue::from_str("create_recovery_record requires main_ciphertext")
        })?,
    )?;
    let signer = parse_secret(
        params
            .get("signer_secret")
            .and_then(Value::as_str)
            .ok_or_else(|| JsValue::from_str("create_recovery_record requires signer_secret"))?,
    )?;
    let mut rng = ChaCha20Rng::from_seed(parse_seed(
        params
            .get("seed_hex")
            .and_then(Value::as_str)
            .ok_or_else(|| JsValue::from_str("create_recovery_record requires seed_hex"))?,
    )?);
    let record = RecoveryRecord::create(
        amount,
        &recipient_key,
        metadata,
        &main_ciphertext,
        &signer,
        &mut rng,
    )
    .map_err(js_error)?;
    serde_json::to_string(&record).map_err(js_error)
}

fn verify_statement(
    statement_json: &str,
    envelope_json: &str,
    verifying_key_bytes: &[u8],
) -> Result<String, JsValue> {
    let statement: Statement = serde_json::from_str(statement_json).map_err(js_error)?;
    let envelope: ProofEnvelope = serde_json::from_str(envelope_json).map_err(js_error)?;
    verify_with_vk_bytes(&statement, &envelope, verifying_key_bytes).map_err(js_error)?;
    Ok("true".to_string())
}

fn execute_inner(request_json: &str, artifact_bytes: &[u8]) -> Result<String, JsValue> {
    let request: Request = serde_json::from_str(request_json).map_err(js_error)?;
    match request.method.as_str() {
        "keygen" => keygen(
            request
                .params
                .get("seed_hex")
                .and_then(Value::as_str)
                .ok_or_else(|| JsValue::from_str("keygen requires seed_hex"))?,
        ),
        "public_key_from_secret" => {
            let secret = parse_secret(
                request
                    .params
                    .get("secret_key")
                    .and_then(Value::as_str)
                    .ok_or_else(|| {
                        JsValue::from_str("public_key_from_secret requires secret_key")
                    })?,
            )?;
            serde_json::to_string(&secret.public_key()).map_err(js_error)
        }
        "encrypt_amount" => encrypt_amount(
            request
                .params
                .get("public_key")
                .and_then(Value::as_str)
                .ok_or_else(|| JsValue::from_str("encrypt_amount requires public_key"))?,
            parse_amount(&request.params, "amount")?,
            request
                .params
                .get("randomness")
                .and_then(Value::as_str)
                .ok_or_else(|| JsValue::from_str("encrypt_amount requires randomness"))?,
        ),
        "decrypt_bounded" => {
            let secret = parse_secret(
                request
                    .params
                    .get("secret_key")
                    .and_then(Value::as_str)
                    .ok_or_else(|| JsValue::from_str("decrypt_bounded requires secret_key"))?,
            )?;
            let ciphertext = parse_ciphertext(
                request
                    .params
                    .get("ciphertext")
                    .and_then(Value::as_str)
                    .ok_or_else(|| JsValue::from_str("decrypt_bounded requires ciphertext"))?,
            )?;
            let max_amount = parse_amount(&request.params, "max_amount")?;
            serde_json::to_string(
                &ciphertext
                    .decrypt_bounded(&secret, max_amount)
                    .map_err(js_error)?
                    .to_string(),
            )
            .map_err(js_error)
        }
        "verify_plaintext_u128" => {
            let secret = parse_secret(
                request
                    .params
                    .get("secret_key")
                    .and_then(Value::as_str)
                    .ok_or_else(|| {
                        JsValue::from_str("verify_plaintext_u128 requires secret_key")
                    })?,
            )?;
            let ciphertext = parse_ciphertext(
                request
                    .params
                    .get("ciphertext")
                    .and_then(Value::as_str)
                    .ok_or_else(|| {
                        JsValue::from_str("verify_plaintext_u128 requires ciphertext")
                    })?,
            )?;
            let amount = parse_amount_u128(&request.params, "amount")?;
            serde_json::to_string(
                &ciphertext
                    .verify_plaintext_u128(&secret, amount)
                    .map_err(js_error)?,
            )
            .map_err(js_error)
        }
        "decrypt_recovery_pair" => {
            let secret = parse_secret(
                request
                    .params
                    .get("secret_key")
                    .and_then(Value::as_str)
                    .ok_or_else(|| {
                        JsValue::from_str("decrypt_recovery_pair requires secret_key")
                    })?,
            )?;
            let expected_key: PublicKey =
                parse_json(request.params.get("expected_key").ok_or_else(|| {
                    JsValue::from_str("decrypt_recovery_pair requires expected_key")
                })?)?;
            let pair: RecoveryPair = parse_json(
                request
                    .params
                    .get("pair")
                    .ok_or_else(|| JsValue::from_str("decrypt_recovery_pair requires pair"))?,
            )?;
            serde_json::to_string(
                &crate::recover_pair(&pair, &secret, &expected_key)
                    .map_err(js_error)?
                    .to_string(),
            )
            .map_err(js_error)
        }
        "canonical_statement" => canonical_statement(
            request
                .params
                .get("statement")
                .and_then(Value::as_str)
                .ok_or_else(|| JsValue::from_str("canonical_statement requires statement"))?,
        ),
        "prove" => prove_statement(
            request
                .params
                .get("statement")
                .and_then(Value::as_str)
                .ok_or_else(|| JsValue::from_str("prove requires statement"))?,
            request
                .params
                .get("witness")
                .and_then(Value::as_str)
                .ok_or_else(|| JsValue::from_str("prove requires witness"))?,
            artifact_bytes,
            request
                .params
                .get("seed_hex")
                .and_then(Value::as_str)
                .ok_or_else(|| JsValue::from_str("prove requires seed_hex"))?,
        ),
        "encrypt_views" => encrypt_views(&request.params),
        "create_recovery_record" => create_recovery_record(&request.params),
        "verify" => verify_statement(
            request
                .params
                .get("statement")
                .and_then(Value::as_str)
                .ok_or_else(|| JsValue::from_str("verify requires statement"))?,
            request
                .params
                .get("envelope")
                .and_then(Value::as_str)
                .ok_or_else(|| JsValue::from_str("verify requires envelope"))?,
            artifact_bytes,
        ),
        "ciphertext_add" | "ciphertext_sub" => {
            let left = parse_ciphertext(
                request
                    .params
                    .get("left")
                    .and_then(Value::as_str)
                    .ok_or_else(|| JsValue::from_str("ciphertext operation requires left"))?,
            )?;
            let right = parse_ciphertext(
                request
                    .params
                    .get("right")
                    .and_then(Value::as_str)
                    .ok_or_else(|| JsValue::from_str("ciphertext operation requires right"))?,
            )?;
            let result = if request.method == "ciphertext_add" {
                left.add(&right)
            } else {
                left.sub(&right)
            }
            .map_err(js_error)?;
            serde_json::to_string(&result).map_err(js_error)
        }
        "commitment_create" => {
            let amount = parse_amount_u128(&request.params, "amount")?;
            let blind = crate::ScalarHex::parse(
                request
                    .params
                    .get("blinding")
                    .and_then(Value::as_str)
                    .ok_or_else(|| JsValue::from_str("commitment_create requires blinding"))?,
            )
            .map_err(js_error)?
            .to_scalar()
            .map_err(js_error)?;
            let commitment = Commitment::commit_u128_with_blinding(amount, blind).map_err(js_error)?;
            serde_json::to_string(&commitment).map_err(js_error)
        }
        "decrypt_recovery_record" => {
            let record: RecoveryRecord = parse_json(
                request
                    .params
                    .get("record")
                    .ok_or_else(|| JsValue::from_str("decrypt_recovery_pair requires record"))?,
            )?;
            let secret = parse_secret(
                request
                    .params
                    .get("secret_key")
                    .and_then(Value::as_str)
                    .ok_or_else(|| {
                        JsValue::from_str("decrypt_recovery_pair requires secret_key")
                    })?,
            )?;
            let key: PublicKey = parse_json(
                request
                    .params
                    .get("expected_recipient_key")
                    .ok_or_else(|| JsValue::from_str("decrypt_recovery_pair requires key"))?,
            )?;
            let ciphertext: Ciphertext =
                parse_json(request.params.get("main_ciphertext").ok_or_else(|| {
                    JsValue::from_str("decrypt_recovery_pair requires ciphertext")
                })?)?;
            let metadata: RecoveryMetadata =
                parse_json(request.params.get("metadata").ok_or_else(|| {
                    JsValue::from_str("decrypt_recovery_pair requires metadata")
                })?)?;
            serde_json::to_string(
                &record
                    .recover(&secret, &key, &ciphertext, &metadata)
                    .map_err(js_error)?
                    .to_string(),
            )
            .map_err(js_error)
        }
        _ => Err(JsValue::from_str("unknown crypto method")),
    }
}

#[wasm_bindgen]
pub fn profile_hash() -> String {
    hex::encode(PROFILE_HASH)
}

#[wasm_bindgen]
pub fn execute(request_json: &str, artifact_bytes: &[u8]) -> Result<String, JsValue> {
    execute_inner(request_json, artifact_bytes)
}

#[wasm_bindgen]
pub fn generate_key(seed_hex: &str) -> Result<String, JsValue> {
    keygen(seed_hex)
}

#[wasm_bindgen]
pub fn public_key_from_secret(secret_key: &str) -> Result<String, JsValue> {
    let secret = parse_secret(secret_key)?;
    serde_json::to_string(&secret.public_key()).map_err(js_error)
}

#[wasm_bindgen]
pub fn encrypt_amount_wire(
    public_key: &str,
    amount: &str,
    randomness: &str,
) -> Result<String, JsValue> {
    let amount = crate::encoding::decimal_u64::parse(amount).map_err(js_error)?;
    encrypt_amount(public_key, amount, randomness)
}

#[wasm_bindgen]
pub fn encrypt_views_wire(params_json: &str) -> Result<String, JsValue> {
    let params: Value = serde_json::from_str(params_json).map_err(js_error)?;
    encrypt_views(&params)
}

#[wasm_bindgen]
pub fn decrypt_amount_wire(
    secret_key: &str,
    ciphertext: &str,
    max_amount: &str,
) -> Result<String, JsValue> {
    let secret = parse_secret(secret_key)?;
    let ciphertext = parse_ciphertext(ciphertext)?;
    let max_amount = crate::encoding::decimal_u64::parse(max_amount).map_err(js_error)?;
    ciphertext
        .decrypt_bounded(&secret, max_amount)
        .map(|amount| amount.to_string())
        .map_err(js_error)
}

#[wasm_bindgen]
pub fn verify_plaintext_u128_wire(
    secret_key: &str,
    ciphertext: &str,
    amount: &str,
) -> Result<bool, JsValue> {
    let secret = parse_secret(secret_key)?;
    let ciphertext = parse_ciphertext(ciphertext)?;
    let amount = crate::encoding::decimal_u128::parse(amount).map_err(js_error)?;
    ciphertext
        .verify_plaintext_u128(&secret, amount)
        .map_err(js_error)
}

#[wasm_bindgen]
pub fn canonical_statement_wire(statement: &str) -> Result<String, JsValue> {
    canonical_statement(statement)
}

#[wasm_bindgen]
pub fn prove_wire(
    statement: &str,
    witness: &str,
    proving_key_bytes: &[u8],
    seed_hex: &str,
) -> Result<String, JsValue> {
    prove_statement(statement, witness, proving_key_bytes, seed_hex)
}

#[wasm_bindgen]
pub fn verify_wire(
    statement: &str,
    envelope: &str,
    verifying_key_bytes: &[u8],
) -> Result<String, JsValue> {
    verify_statement(statement, envelope, verifying_key_bytes)
}
